<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {useRoute} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import ImageUploader from '@/components/ImageUploader.vue';import RichTextEditor from '@/components/RichTextEditor.vue';import {deleteCatalog,getCatalog,listCatalog,saveCatalog,type CatalogRecord} from '@/api/catalog';import type {UploadFileRecord} from '@/types/api'
const route=useRoute(),kind=computed(()=>String(route.meta.catalogKind)),title=computed(()=>String(route.meta.title)),items=ref<CatalogRecord[]>([]),parentOptions=ref<CatalogRecord[]>([]),total=ref(0),loading=ref(false),dialog=ref(false),q=reactive({page:1,pageSize:10,keyword:'',status:'',resourceType:''}),types=[['pattern','纹样素材'],['document','文献资料'],['creation','共创作品'],['inheritor','传承人'],['application_case','应用案例']]
const blank=()=>({id:undefined as number|undefined,name:'',title:'',slug:'',description:'',status:'draft',sortOrder:0,resourceType:'pattern',parentId:null as number|null,subtitle:'',image:null as UploadFileRecord|null,linkUrl:'',linkText:'',startAt:'',endAt:'',pageKey:'',content:'',tags:[] as string[],isFeatured:false,cover:null as UploadFileRecord|null});let form=reactive(blank())
async function load(){loading.value=true;try{const r=await listCatalog(kind.value,{...q,status:q.status||undefined,resourceType:q.resourceType||undefined});items.value=r.items;total.value=r.total}finally{loading.value=false}}async function loadParents(){if(kind.value!=='categories')return;parentOptions.value=(await listCatalog('categories',{page:1,pageSize:100,resourceType:form.resourceType})).items.filter(x=>x.id!==form.id)}async function create(){Object.assign(form,blank());await loadParents();dialog.value=true}
async function edit(row:CatalogRecord){const d=await getCatalog(kind.value,row.id);Object.assign(form,blank(),d,{id:d.id,sortOrder:d.sort_order||0,resourceType:d.resource_type||'pattern',parentId:d.parent_id||null,image:d.image_url?{id:'0',file_url:d.image_url,file_name:'',file_size:0,file_type:'image'}:null,cover:d.cover_image?{id:'0',file_url:d.cover_image,file_name:'',file_size:0,file_type:'image'}:null,linkUrl:d.link_url||'',linkText:d.link_text||'',startAt:d.start_at||'',endAt:d.end_at||'',pageKey:d.page_key||'',isFeatured:Boolean(d.is_featured),tags:Array.isArray(d.tags)?d.tags:[]});await loadParents();dialog.value=true}
async function save(){let data:any;if(kind.value==='categories')data={resourceType:form.resourceType,parentId:form.parentId,name:form.name,slug:form.slug,description:form.description||null,status:form.status,sortOrder:form.sortOrder};else if(kind.value==='tags')data={name:form.name,slug:form.slug,description:form.description||null,status:form.status,sortOrder:form.sortOrder};else if(kind.value==='banners')data={title:form.title,subtitle:form.subtitle||null,imageUrl:form.image?.file_url||'',linkUrl:form.linkUrl||null,linkText:form.linkText||null,status:form.status,sortOrder:form.sortOrder,startAt:form.startAt||null,endAt:form.endAt||null};else data={pageKey:form.pageKey,title:form.title,coverImage:form.cover?.file_url||null,description:form.description||null,content:form.content||null,tags:form.tags,status:form.status,sortOrder:form.sortOrder,isFeatured:form.isFeatured};await saveCatalog(kind.value,form.id,data);ElMessage.success('保存成功');dialog.value=false;await load()}async function remove(row:CatalogRecord){await ElMessageBox.confirm('确定删除该记录吗？','删除确认',{type:'warning'});await deleteCatalog(kind.value,row.id);ElMessage.success('删除成功');await load()}onMounted(load)
</script>
<template><section><div class="manager-head"><div><span class="eyebrow">CATALOG CMS</span><h1>{{title}}</h1></div><el-button type="primary" @click="create">新增</el-button></div><el-card><el-form inline><el-form-item label="搜索"><el-input v-model="q.keyword" clearable @keyup.enter="load"/></el-form-item><el-form-item label="状态"><el-select v-model="q.status" clearable style="width:130px"><el-option label="草稿" value="draft"/><el-option label="已上架" value="published"/><el-option label="已下架" value="offline"/></el-select></el-form-item><el-form-item v-if="kind==='categories'" label="内容类型"><el-select v-model="q.resourceType" clearable style="width:150px"><el-option v-for="t in types" :key="t[0]" :label="t[1]" :value="t[0]"/></el-select></el-form-item><el-button type="primary" @click="q.page=1;load()">查询</el-button></el-form><el-table v-loading="loading" :data="items"><el-table-column prop="id" label="ID" width="70"/><el-table-column :prop="kind==='categories'||kind==='tags'?'name':'title'" label="名称 / 标题"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="sort_order" label="排序" width="90"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="q.page" :total="total" layout="total, prev, pager, next" @change="load"/></el-card><el-dialog v-model="dialog" :title="form.id?'编辑':'新增'" width="680px"><el-form label-position="top"><template v-if="kind==='categories'||kind==='tags'"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="Slug"><el-input v-model="form.slug"/></el-form-item><el-form-item v-if="kind==='categories'" label="内容类型"><el-select v-model="form.resourceType" @change="form.parentId=null;loadParents()"><el-option v-for="t in types" :key="t[0]" :label="t[1]" :value="t[0]"/></el-select></el-form-item><el-form-item v-if="kind==='categories'" label="父分类"><el-select v-model="form.parentId" clearable placeholder="无父分类"><el-option v-for="parent in parentOptions" :key="parent.id" :label="parent.name" :value="parent.id"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></template><template v-else-if="kind==='banners'"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="副标题"><el-input v-model="form.subtitle"/></el-form-item><el-form-item label="图片"><ImageUploader v-model="form.image"/></el-form-item><el-form-item label="链接"><el-input v-model="form.linkUrl"/></el-form-item><el-form-item label="按钮文字"><el-input v-model="form.linkText"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="开始时间"><el-date-picker v-model="form.startAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item></el-col><el-col :span="12"><el-form-item label="结束时间"><el-date-picker v-model="form.endAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item></el-col></el-row></template><template v-else><el-form-item label="页面 Key"><el-input v-model="form.pageKey"/></el-form-item><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="封面"><ImageUploader v-model="form.cover"/></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="正文"><RichTextEditor v-model="form.content"/></el-form-item><el-form-item label="标签"><el-select v-model="form.tags" multiple allow-create filterable/></el-form-item><el-form-item label="首页推荐"><el-switch v-model="form.isFeatured"/></el-form-item></template><el-row :gutter="16"><el-col :span="12"><el-form-item label="状态"><el-select v-model="form.status"><el-option label="草稿" value="draft"/><el-option label="已上架" value="published"/><el-option label="已下架" value="offline"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="排序"><el-input-number v-model="form.sortOrder"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
